CREATE TABLE IF NOT EXISTS "projects" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- URL segment and the key used in dashboard links.
	"slug" VARCHAR(80) NOT NULL UNIQUE,
	-- Display name.
	"name" VARCHAR(160) NOT NULL,
	-- Public key the SDK sends with every batch. Public on purpose - it can only write - which is why ingestion still validates shape and rate rather than trusting it.
	"write_key" VARCHAR(64) NOT NULL UNIQUE,
	-- IANA zone the day boundary is drawn on. Daily active users is a local-calendar question, and bucketing in UTC is what makes a Monday number disagree with the customer own dashboard.
	"reporting_timezone" VARCHAR(64) NOT NULL DEFAULT 'UTC',
	-- How long rows in events survive. The single largest cost lever in the product, and the reason snapshots exist.
	"raw_event_retention_days" INTEGER NOT NULL DEFAULT 730,
	-- How long an inactive person profile survives. Null means keep indefinitely, which is legal only with a lawful basis.
	"person_retention_days" INTEGER,
	-- Suspends ingestion without deleting anything.
	"is_active" BOOLEAN NOT NULL DEFAULT true,
	-- Project creation time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "projects" IS 'A data silo. Every other table is scoped by project because cross-project queries are never a feature and the scoping column is what makes partitioning and per-customer deletion possible.';
COMMENT ON COLUMN "projects"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "projects"."slug" IS 'URL segment and the key used in dashboard links.';
COMMENT ON COLUMN "projects"."name" IS 'Display name.';
COMMENT ON COLUMN "projects"."write_key" IS 'Public key the SDK sends with every batch. Public on purpose - it can only write - which is why ingestion still validates shape and rate rather than trusting it.';
COMMENT ON COLUMN "projects"."reporting_timezone" IS 'IANA zone the day boundary is drawn on. Daily active users is a local-calendar question, and bucketing in UTC is what makes a Monday number disagree with the customer own dashboard.';
COMMENT ON COLUMN "projects"."raw_event_retention_days" IS 'How long rows in events survive. The single largest cost lever in the product, and the reason snapshots exist.';
COMMENT ON COLUMN "projects"."person_retention_days" IS 'How long an inactive person profile survives. Null means keep indefinitely, which is legal only with a lawful basis.';
COMMENT ON COLUMN "projects"."is_active" IS 'Suspends ingestion without deleting anything.';
COMMENT ON COLUMN "projects"."created_at" IS 'Project creation time.';

CREATE TABLE IF NOT EXISTS "event_definitions" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Owning project.
	"project_id" BIGINT NOT NULL,
	-- Event name as sent by the SDK, e.g. checkout_completed. Registered on first sight rather than declared up front.
	"name" VARCHAR(120) NOT NULL,
	-- Friendly label set by an analyst. Null until somebody curates it.
	"display_name" VARCHAR(160),
	-- Grouping for the event picker, e.g. billing or onboarding. Null for unsorted events.
	"category" VARCHAR(60),
	-- Observed property names with inferred types and cardinality. Built by a sampler, not enforced, so a typo shows up as a new key instead of a rejected payload.
	"property_schema" JSONB,
	-- Hides an event from pickers without dropping its data. Every project accumulates dozens of test events nobody wants to see again.
	"is_hidden" BOOLEAN NOT NULL DEFAULT false,
	-- First arrival. Instrumentation regressions are usually visible as a gap between this and last_seen_at.
	"first_seen_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- Most recent arrival, updated cheaply by ingestion.
	"last_seen_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "event_definitions" IS 'The schema registry, discovered rather than declared. It exists so the UI can offer a list of event names without a DISTINCT over billions of rows, and so an analyst has somewhere to put the meaning of an event.';
COMMENT ON COLUMN "event_definitions"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "event_definitions"."project_id" IS 'Owning project.';
COMMENT ON COLUMN "event_definitions"."name" IS 'Event name as sent by the SDK, e.g. checkout_completed. Registered on first sight rather than declared up front.';
COMMENT ON COLUMN "event_definitions"."display_name" IS 'Friendly label set by an analyst. Null until somebody curates it.';
COMMENT ON COLUMN "event_definitions"."category" IS 'Grouping for the event picker, e.g. billing or onboarding. Null for unsorted events.';
COMMENT ON COLUMN "event_definitions"."property_schema" IS 'Observed property names with inferred types and cardinality. Built by a sampler, not enforced, so a typo shows up as a new key instead of a rejected payload.';
COMMENT ON COLUMN "event_definitions"."is_hidden" IS 'Hides an event from pickers without dropping its data. Every project accumulates dozens of test events nobody wants to see again.';
COMMENT ON COLUMN "event_definitions"."first_seen_at" IS 'First arrival. Instrumentation regressions are usually visible as a gap between this and last_seen_at.';
COMMENT ON COLUMN "event_definitions"."last_seen_at" IS 'Most recent arrival, updated cheaply by ingestion.';

CREATE UNIQUE INDEX "uq_event_defs_project_name"
ON "event_definitions" ("project_id", "name");

CREATE TABLE IF NOT EXISTS "events" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Owning project. Present on every row because it is the partition and deletion key.
	"project_id" BIGINT NOT NULL,
	-- Resolved event type. A foreign key rather than a repeated name string, which keeps the widest table in the system narrow.
	"event_definition_id" BIGINT NOT NULL,
	-- Resolved identity. Null for traffic that was never identified, and rewritten in bulk when an identity merge happens.
	"person_id" BIGINT,
	-- Device or browser identifier from the SDK. Always present, because every event has a sender even when it has no known user.
	"anonymous_id" VARCHAR(80) NOT NULL,
	-- Session the event fell into. Null for server-side events, which have no browsing session to belong to.
	"session_id" BIGINT,
	-- Client-generated unique id for the event. The deduplication key that makes an SDK retry after a network failure safe.
	"insert_id" VARCHAR(80) NOT NULL,
	-- Arbitrary event properties. JSONB rather than an attribute-value table - see the table note - and indexed with a GIN index in production.
	"properties" JSONB,
	-- Environment captured at send time: page, referrer, user agent, SDK version, locale. Separated from properties so product fields and transport fields are never confused.
	"context" JSONB,
	-- When it happened on the client. The analysis timestamp, and the reason late-arriving data must be handled rather than assumed away.
	"occurred_at" TIMESTAMPTZ NOT NULL,
	-- When ingestion accepted it. The gap to occurred_at is clock skew plus offline buffering, and events with an implausible gap are quarantined.
	"received_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "events" IS 'The raw stream, append-only and partitioned by occurred_at. Properties are one JSONB column instead of an entity-attribute-value table because EAV turns a single event into a dozen rows and every funnel query into a dozen self-joins; JSONB keeps the event atomic and is still queryable and indexable.';
COMMENT ON COLUMN "events"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "events"."project_id" IS 'Owning project. Present on every row because it is the partition and deletion key.';
COMMENT ON COLUMN "events"."event_definition_id" IS 'Resolved event type. A foreign key rather than a repeated name string, which keeps the widest table in the system narrow.';
COMMENT ON COLUMN "events"."person_id" IS 'Resolved identity. Null for traffic that was never identified, and rewritten in bulk when an identity merge happens.';
COMMENT ON COLUMN "events"."anonymous_id" IS 'Device or browser identifier from the SDK. Always present, because every event has a sender even when it has no known user.';
COMMENT ON COLUMN "events"."session_id" IS 'Session the event fell into. Null for server-side events, which have no browsing session to belong to.';
COMMENT ON COLUMN "events"."insert_id" IS 'Client-generated unique id for the event. The deduplication key that makes an SDK retry after a network failure safe.';
COMMENT ON COLUMN "events"."properties" IS 'Arbitrary event properties. JSONB rather than an attribute-value table - see the table note - and indexed with a GIN index in production.';
COMMENT ON COLUMN "events"."context" IS 'Environment captured at send time: page, referrer, user agent, SDK version, locale. Separated from properties so product fields and transport fields are never confused.';
COMMENT ON COLUMN "events"."occurred_at" IS 'When it happened on the client. The analysis timestamp, and the reason late-arriving data must be handled rather than assumed away.';
COMMENT ON COLUMN "events"."received_at" IS 'When ingestion accepted it. The gap to occurred_at is clock skew plus offline buffering, and events with an implausible gap are quarantined.';

CREATE UNIQUE INDEX "uq_events_project_insert"
ON "events" ("project_id", "insert_id");
CREATE INDEX "idx_events_project_time"
ON "events" ("project_id", "occurred_at");
CREATE INDEX "idx_events_person_time"
ON "events" ("person_id", "occurred_at");
CREATE INDEX "idx_events_definition_time"
ON "events" ("event_definition_id", "occurred_at");

CREATE TABLE IF NOT EXISTS "persons" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Owning project. Identity never spans projects.
	"project_id" BIGINT NOT NULL,
	-- The identifier the profile is displayed under, usually the application user id once known and the first anonymous id before that.
	"canonical_distinct_id" VARCHAR(120) NOT NULL,
	-- True once an identify call attached a real user id. Anonymous profiles are still real rows, because most funnels start before login.
	"is_identified" BOOLEAN NOT NULL DEFAULT false,
	-- Last-known user properties: plan, company, signup source. Overwritten rather than versioned, which is why anything needed historically belongs on the event instead.
	"traits" JSONB,
	-- Set when this profile was absorbed by another. The row is kept as a tombstone so stale references resolve rather than dangle.
	"merged_into_person_id" BIGINT,
	-- Earliest activity attributed to this profile. It moves backwards on a merge, which is exactly what makes the merge worth doing.
	"first_seen_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- Most recent activity.
	"last_seen_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "persons" IS 'One human, as far as the system can tell. Profiles are created optimistically for anonymous traffic and merged later, because refusing to track anyone until they log in loses the entire acquisition funnel.';
COMMENT ON COLUMN "persons"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "persons"."project_id" IS 'Owning project. Identity never spans projects.';
COMMENT ON COLUMN "persons"."canonical_distinct_id" IS 'The identifier the profile is displayed under, usually the application user id once known and the first anonymous id before that.';
COMMENT ON COLUMN "persons"."is_identified" IS 'True once an identify call attached a real user id. Anonymous profiles are still real rows, because most funnels start before login.';
COMMENT ON COLUMN "persons"."traits" IS 'Last-known user properties: plan, company, signup source. Overwritten rather than versioned, which is why anything needed historically belongs on the event instead.';
COMMENT ON COLUMN "persons"."merged_into_person_id" IS 'Set when this profile was absorbed by another. The row is kept as a tombstone so stale references resolve rather than dangle.';
COMMENT ON COLUMN "persons"."first_seen_at" IS 'Earliest activity attributed to this profile. It moves backwards on a merge, which is exactly what makes the merge worth doing.';
COMMENT ON COLUMN "persons"."last_seen_at" IS 'Most recent activity.';

CREATE UNIQUE INDEX "uq_persons_project_distinct"
ON "persons" ("project_id", "canonical_distinct_id");
CREATE INDEX "idx_persons_merged_into"
ON "persons" ("merged_into_person_id");

CREATE TABLE IF NOT EXISTS "person_identifiers" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Owning project.
	"project_id" BIGINT NOT NULL,
	-- Profile the identifier currently resolves to. Rewritten when a merge moves the identifier to a surviving profile.
	"person_id" BIGINT NOT NULL,
	-- anonymous_id | user_id | email | device_id | external_id. Types are ranked - a user_id outranks an anonymous_id when deciding which profile survives a merge.
	"identifier_type" VARCHAR(24) NOT NULL,
	-- The identifier itself. Emails are lowercased before storage, because otherwise the same person arrives twice.
	"value" VARCHAR(200) NOT NULL,
	-- First time this identifier was observed.
	"first_seen_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- Most recent observation, used to age out stale device ids.
	"last_seen_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "person_identifiers" IS 'The identity graph, as edges from an identifier to a profile. The unique key on type and value is the whole resolution algorithm: an incoming identifier either already points somewhere, or it is new, or it points somewhere else and two profiles must merge.';
COMMENT ON COLUMN "person_identifiers"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "person_identifiers"."project_id" IS 'Owning project.';
COMMENT ON COLUMN "person_identifiers"."person_id" IS 'Profile the identifier currently resolves to. Rewritten when a merge moves the identifier to a surviving profile.';
COMMENT ON COLUMN "person_identifiers"."identifier_type" IS 'anonymous_id | user_id | email | device_id | external_id. Types are ranked - a user_id outranks an anonymous_id when deciding which profile survives a merge.';
COMMENT ON COLUMN "person_identifiers"."value" IS 'The identifier itself. Emails are lowercased before storage, because otherwise the same person arrives twice.';
COMMENT ON COLUMN "person_identifiers"."first_seen_at" IS 'First time this identifier was observed.';
COMMENT ON COLUMN "person_identifiers"."last_seen_at" IS 'Most recent observation, used to age out stale device ids.';

CREATE UNIQUE INDEX "uq_identifiers_project_type_value"
ON "person_identifiers" ("project_id", "identifier_type", "value");
CREATE INDEX "idx_identifiers_person"
ON "person_identifiers" ("person_id");

CREATE TABLE IF NOT EXISTS "identity_merges" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Owning project.
	"project_id" BIGINT NOT NULL,
	-- Profile that was absorbed. It survives as a tombstone with merged_into_person_id set.
	"source_person_id" BIGINT NOT NULL,
	-- Profile that survived. Chosen by identifier rank and then by age, never arbitrarily, so the same inputs always merge the same way.
	"target_person_id" BIGINT NOT NULL,
	-- identify | alias | manual | backfill. Manual merges by an operator are the ones that get questioned later, which is why the trigger is recorded.
	"trigger" VARCHAR(24) NOT NULL,
	-- Identifier that collided and caused the merge. Null for a manual merge.
	"identifier_type" VARCHAR(24),
	-- Value that collided. Null for a manual merge.
	"identifier_value" VARCHAR(200),
	-- How many event rows had person_id rewritten. Records the cost of the merge, which is what makes an accidental mass merge visible immediately.
	"events_reassigned" BIGINT NOT NULL DEFAULT 0,
	-- Set if the merge was undone. Reversal is only possible because this table records exactly what moved.
	"is_reversed" BOOLEAN NOT NULL DEFAULT false,
	-- When it happened.
	"merged_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "identity_merges" IS 'An audit log of identity resolution, and the hardest table in the schema to do without. Merges are destructive and occasionally wrong - a shared kiosk browser can fuse two real people - so every one records what triggered it and what it moved.';
COMMENT ON COLUMN "identity_merges"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "identity_merges"."project_id" IS 'Owning project.';
COMMENT ON COLUMN "identity_merges"."source_person_id" IS 'Profile that was absorbed. It survives as a tombstone with merged_into_person_id set.';
COMMENT ON COLUMN "identity_merges"."target_person_id" IS 'Profile that survived. Chosen by identifier rank and then by age, never arbitrarily, so the same inputs always merge the same way.';
COMMENT ON COLUMN "identity_merges"."trigger" IS 'identify | alias | manual | backfill. Manual merges by an operator are the ones that get questioned later, which is why the trigger is recorded.';
COMMENT ON COLUMN "identity_merges"."identifier_type" IS 'Identifier that collided and caused the merge. Null for a manual merge.';
COMMENT ON COLUMN "identity_merges"."identifier_value" IS 'Value that collided. Null for a manual merge.';
COMMENT ON COLUMN "identity_merges"."events_reassigned" IS 'How many event rows had person_id rewritten. Records the cost of the merge, which is what makes an accidental mass merge visible immediately.';
COMMENT ON COLUMN "identity_merges"."is_reversed" IS 'Set if the merge was undone. Reversal is only possible because this table records exactly what moved.';
COMMENT ON COLUMN "identity_merges"."merged_at" IS 'When it happened.';

CREATE INDEX "idx_merges_project_time"
ON "identity_merges" ("project_id", "merged_at");
CREATE INDEX "idx_merges_source"
ON "identity_merges" ("source_person_id");
CREATE INDEX "idx_merges_target"
ON "identity_merges" ("target_person_id");

CREATE TABLE IF NOT EXISTS "sessions" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Owning project.
	"project_id" BIGINT NOT NULL,
	-- Profile the session belongs to, once known. Null for a session that never identified, and rewritten by a merge.
	"person_id" BIGINT,
	-- Device the session ran on. A session never spans devices, which is why this is not nullable even when the person is known.
	"anonymous_id" VARCHAR(80) NOT NULL,
	-- First event in the session.
	"started_at" TIMESTAMPTZ NOT NULL,
	-- Last event, plus the inactivity timeout. Null while the session is still open.
	"ended_at" TIMESTAMPTZ,
	-- Closed session length, stored so engagement reporting does not subtract timestamps on millions of rows.
	"duration_seconds" INTEGER,
	-- Events in the session. A count of one is the definition of a bounce.
	"event_count" INTEGER NOT NULL DEFAULT 0,
	-- First page. Null for a session that began with a server-side or mobile event.
	"entry_path" VARCHAR(500),
	-- Last page seen.
	"exit_path" VARCHAR(500),
	-- Where the visit came from. Domain only, because the full referrer is high cardinality and rarely useful.
	"referrer_domain" VARCHAR(200),
	-- desktop | mobile | tablet | server. Derived at ingestion from the user agent.
	"device_type" VARCHAR(24),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "sessions" IS 'A window of activity, derived at ingestion rather than at query time. Sessionising on read means every dashboard reimplements the timeout rule slightly differently; computing it once makes session-based metrics agree with each other.';
COMMENT ON COLUMN "sessions"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "sessions"."project_id" IS 'Owning project.';
COMMENT ON COLUMN "sessions"."person_id" IS 'Profile the session belongs to, once known. Null for a session that never identified, and rewritten by a merge.';
COMMENT ON COLUMN "sessions"."anonymous_id" IS 'Device the session ran on. A session never spans devices, which is why this is not nullable even when the person is known.';
COMMENT ON COLUMN "sessions"."started_at" IS 'First event in the session.';
COMMENT ON COLUMN "sessions"."ended_at" IS 'Last event, plus the inactivity timeout. Null while the session is still open.';
COMMENT ON COLUMN "sessions"."duration_seconds" IS 'Closed session length, stored so engagement reporting does not subtract timestamps on millions of rows.';
COMMENT ON COLUMN "sessions"."event_count" IS 'Events in the session. A count of one is the definition of a bounce.';
COMMENT ON COLUMN "sessions"."entry_path" IS 'First page. Null for a session that began with a server-side or mobile event.';
COMMENT ON COLUMN "sessions"."exit_path" IS 'Last page seen.';
COMMENT ON COLUMN "sessions"."referrer_domain" IS 'Where the visit came from. Domain only, because the full referrer is high cardinality and rarely useful.';
COMMENT ON COLUMN "sessions"."device_type" IS 'desktop | mobile | tablet | server. Derived at ingestion from the user agent.';

CREATE INDEX "idx_sessions_project_started"
ON "sessions" ("project_id", "started_at");
CREATE INDEX "idx_sessions_person_started"
ON "sessions" ("person_id", "started_at");

CREATE TABLE IF NOT EXISTS "funnels" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Owning project.
	"project_id" BIGINT NOT NULL,
	-- Display name.
	"name" VARCHAR(160) NOT NULL,
	-- How long a user has to finish after starting. Without a window, a funnel silently counts someone who signed up in January and paid in November as a conversion.
	"conversion_window_seconds" INTEGER NOT NULL DEFAULT 604800,
	-- strict_order | any_order. Strict requires the steps in sequence; any_order only requires that all of them happened inside the window.
	"counting_method" VARCHAR(20) NOT NULL DEFAULT 'strict_order',
	-- Property to split the funnel by, e.g. plan or country. Null for an unsegmented funnel.
	"breakdown_property" VARCHAR(120),
	-- Creation time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- Last edit. Editing a funnel invalidates its cached snapshots, which is why this timestamp matters.
	"updated_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "funnels" IS 'A saved funnel definition. It stores the question, never the answer - results live in metric_snapshots - so changing the window recomputes rather than corrupting a historical number.';
COMMENT ON COLUMN "funnels"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "funnels"."project_id" IS 'Owning project.';
COMMENT ON COLUMN "funnels"."name" IS 'Display name.';
COMMENT ON COLUMN "funnels"."conversion_window_seconds" IS 'How long a user has to finish after starting. Without a window, a funnel silently counts someone who signed up in January and paid in November as a conversion.';
COMMENT ON COLUMN "funnels"."counting_method" IS 'strict_order | any_order. Strict requires the steps in sequence; any_order only requires that all of them happened inside the window.';
COMMENT ON COLUMN "funnels"."breakdown_property" IS 'Property to split the funnel by, e.g. plan or country. Null for an unsegmented funnel.';
COMMENT ON COLUMN "funnels"."created_at" IS 'Creation time.';
COMMENT ON COLUMN "funnels"."updated_at" IS 'Last edit. Editing a funnel invalidates its cached snapshots, which is why this timestamp matters.';

CREATE TABLE IF NOT EXISTS "funnel_steps" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Funnel the step belongs to.
	"funnel_id" BIGINT NOT NULL,
	-- Position in the sequence, starting at one. The ordinal is the funnel - reordering steps is an update here, not a new funnel.
	"step_index" SMALLINT NOT NULL,
	-- Event that satisfies this step.
	"event_definition_id" BIGINT NOT NULL,
	-- Display label overriding the event name, e.g. Reached checkout. Null to use the event name.
	"label" VARCHAR(120),
	-- Extra property conditions the event must satisfy, e.g. plan equals pro. JSONB because the condition tree is data the UI builds, not something with a fixed column shape.
	"filter" JSONB,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "funnel_steps" IS 'One ordered step. Steps as rows rather than an array column mean a step can carry its own filter and label, and the join to event_definitions stays a normal foreign key.';
COMMENT ON COLUMN "funnel_steps"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "funnel_steps"."funnel_id" IS 'Funnel the step belongs to.';
COMMENT ON COLUMN "funnel_steps"."step_index" IS 'Position in the sequence, starting at one. The ordinal is the funnel - reordering steps is an update here, not a new funnel.';
COMMENT ON COLUMN "funnel_steps"."event_definition_id" IS 'Event that satisfies this step.';
COMMENT ON COLUMN "funnel_steps"."label" IS 'Display label overriding the event name, e.g. Reached checkout. Null to use the event name.';
COMMENT ON COLUMN "funnel_steps"."filter" IS 'Extra property conditions the event must satisfy, e.g. plan equals pro. JSONB because the condition tree is data the UI builds, not something with a fixed column shape.';

CREATE UNIQUE INDEX "uq_funnel_steps_funnel_index"
ON "funnel_steps" ("funnel_id", "step_index");

CREATE TABLE IF NOT EXISTS "cohorts" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Owning project.
	"project_id" BIGINT NOT NULL,
	-- Display name.
	"name" VARCHAR(160) NOT NULL,
	-- The rule: behavioural conditions, trait filters and time bounds as a condition tree. Stored as data so the same definition can be evaluated by the query engine and shown in the editor.
	"definition" JSONB NOT NULL,
	-- True for a frozen list, typically an uploaded set of user ids. False means membership is recomputed on a schedule and can change without anyone acting.
	"is_static" BOOLEAN NOT NULL DEFAULT false,
	-- Size at the last refresh. Denormalised so a list of cohorts renders without counting members.
	"member_count" INTEGER NOT NULL DEFAULT 0,
	-- How often a dynamic cohort is recomputed. Null for static cohorts, which never refresh.
	"refresh_interval_minutes" INTEGER,
	-- End of the last successful recomputation. A stale value here is the usual explanation for a cohort that looks wrong.
	"last_refreshed_at" TIMESTAMPTZ,
	-- Creation time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "cohorts" IS 'A saved audience. Keeping the definition and the materialised membership in separate tables is what lets a cohort be both a live query and a fast join target.';
COMMENT ON COLUMN "cohorts"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "cohorts"."project_id" IS 'Owning project.';
COMMENT ON COLUMN "cohorts"."name" IS 'Display name.';
COMMENT ON COLUMN "cohorts"."definition" IS 'The rule: behavioural conditions, trait filters and time bounds as a condition tree. Stored as data so the same definition can be evaluated by the query engine and shown in the editor.';
COMMENT ON COLUMN "cohorts"."is_static" IS 'True for a frozen list, typically an uploaded set of user ids. False means membership is recomputed on a schedule and can change without anyone acting.';
COMMENT ON COLUMN "cohorts"."member_count" IS 'Size at the last refresh. Denormalised so a list of cohorts renders without counting members.';
COMMENT ON COLUMN "cohorts"."refresh_interval_minutes" IS 'How often a dynamic cohort is recomputed. Null for static cohorts, which never refresh.';
COMMENT ON COLUMN "cohorts"."last_refreshed_at" IS 'End of the last successful recomputation. A stale value here is the usual explanation for a cohort that looks wrong.';
COMMENT ON COLUMN "cohorts"."created_at" IS 'Creation time.';

CREATE TABLE IF NOT EXISTS "cohort_members" (
	-- Cohort being populated. Half of the composite primary key.
	"cohort_id" BIGINT,
	-- Member profile. Half of the composite key, which also makes a repeated refresh idempotent.
	"person_id" BIGINT,
	-- When the profile first qualified. Cohort entry date is what retention curves are anchored on.
	"added_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- When it stopped qualifying. Null for a current member; rows are closed rather than deleted so churn out of a cohort is measurable.
	"removed_at" TIMESTAMPTZ,
	PRIMARY KEY("cohort_id", "person_id")
);

COMMENT ON TABLE "cohort_members" IS 'Materialised membership. Closing rows instead of deleting them turns the membership table into its own history, which is the difference between knowing who is in a cohort and knowing who left it.';
COMMENT ON COLUMN "cohort_members"."cohort_id" IS 'Cohort being populated. Half of the composite primary key.';
COMMENT ON COLUMN "cohort_members"."person_id" IS 'Member profile. Half of the composite key, which also makes a repeated refresh idempotent.';
COMMENT ON COLUMN "cohort_members"."added_at" IS 'When the profile first qualified. Cohort entry date is what retention curves are anchored on.';
COMMENT ON COLUMN "cohort_members"."removed_at" IS 'When it stopped qualifying. Null for a current member; rows are closed rather than deleted so churn out of a cohort is measurable.';

CREATE INDEX "idx_cohort_members_person"
ON "cohort_members" ("person_id");
CREATE INDEX "idx_cohort_members_active"
ON "cohort_members" ("cohort_id", "removed_at");

CREATE TABLE IF NOT EXISTS "retention_reports" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Owning project.
	"project_id" BIGINT NOT NULL,
	-- Display name.
	"name" VARCHAR(160) NOT NULL,
	-- Event that puts a user into the cohort for a period, e.g. signed_up or first_purchase.
	"start_event_definition_id" BIGINT NOT NULL,
	-- Event that counts as coming back. Often deliberately different from the start event, because signing up twice is not retention.
	"return_event_definition_id" BIGINT NOT NULL,
	-- Restricts the report to one audience. Null to measure everybody.
	"cohort_id" BIGINT,
	-- day | week | month. The bucket width of the retention grid, and the only thing that makes a 40 percent figure comparable between two reports.
	"window_unit" VARCHAR(12) NOT NULL DEFAULT 'day',
	-- How many buckets to compute forward from the start event. Bounded because a retention grid is quadratic in this number.
	"window_count" SMALLINT NOT NULL DEFAULT 30,
	-- True for returned on or after bucket N, false for returned exactly in bucket N. The two produce very different curves and are routinely confused.
	"is_rolling" BOOLEAN NOT NULL DEFAULT false,
	-- Creation time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "retention_reports" IS 'A saved retention question. The definition is stored and the grid is not, because a retention grid is expensive, reproducible and only meaningful alongside the exact window rules that produced it.';
COMMENT ON COLUMN "retention_reports"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "retention_reports"."project_id" IS 'Owning project.';
COMMENT ON COLUMN "retention_reports"."name" IS 'Display name.';
COMMENT ON COLUMN "retention_reports"."start_event_definition_id" IS 'Event that puts a user into the cohort for a period, e.g. signed_up or first_purchase.';
COMMENT ON COLUMN "retention_reports"."return_event_definition_id" IS 'Event that counts as coming back. Often deliberately different from the start event, because signing up twice is not retention.';
COMMENT ON COLUMN "retention_reports"."cohort_id" IS 'Restricts the report to one audience. Null to measure everybody.';
COMMENT ON COLUMN "retention_reports"."window_unit" IS 'day | week | month. The bucket width of the retention grid, and the only thing that makes a 40 percent figure comparable between two reports.';
COMMENT ON COLUMN "retention_reports"."window_count" IS 'How many buckets to compute forward from the start event. Bounded because a retention grid is quadratic in this number.';
COMMENT ON COLUMN "retention_reports"."is_rolling" IS 'True for returned on or after bucket N, false for returned exactly in bucket N. The two produce very different curves and are routinely confused.';
COMMENT ON COLUMN "retention_reports"."created_at" IS 'Creation time.';

CREATE TABLE IF NOT EXISTS "metric_snapshots" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Owning project.
	"project_id" BIGINT NOT NULL,
	-- What was computed, e.g. funnel:42:step:3 or dau. A structured key rather than a foreign key, because a snapshot can come from a funnel, a retention report or a built-in metric.
	"metric_key" VARCHAR(160) NOT NULL,
	-- hour | day | week | month. The bucket width. A daily row is not the sum of hourly rows for unique counts, which is why each grain is computed separately.
	"grain" VARCHAR(12) NOT NULL,
	-- Start of the bucket, aligned to the project reporting timezone rather than to UTC.
	"bucket_start" TIMESTAMPTZ NOT NULL,
	-- Breakdown dimension, e.g. country. The literal all means the ungrouped total, so totals and breakdowns share one table.
	"dimension_key" VARCHAR(80) NOT NULL DEFAULT 'all',
	-- Breakdown value. High-cardinality dimensions are truncated to a top-N plus an other bucket before they reach this table.
	"dimension_value" VARCHAR(200) NOT NULL DEFAULT 'all',
	-- The computed number. Numeric rather than float, because a dashboard that shows a different total on refresh destroys trust faster than a slow query.
	"value" NUMERIC(20,4) NOT NULL,
	-- When the rollup ran. A bucket can be recomputed after late events arrive, and this says which version you are looking at.
	"computed_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "metric_snapshots" IS 'Precomputed answers. This table is what lets raw events be deleted on a retention schedule while charts keep working, and the unique key makes a rollup job safely re-runnable after late-arriving data.';
COMMENT ON COLUMN "metric_snapshots"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "metric_snapshots"."project_id" IS 'Owning project.';
COMMENT ON COLUMN "metric_snapshots"."metric_key" IS 'What was computed, e.g. funnel:42:step:3 or dau. A structured key rather than a foreign key, because a snapshot can come from a funnel, a retention report or a built-in metric.';
COMMENT ON COLUMN "metric_snapshots"."grain" IS 'hour | day | week | month. The bucket width. A daily row is not the sum of hourly rows for unique counts, which is why each grain is computed separately.';
COMMENT ON COLUMN "metric_snapshots"."bucket_start" IS 'Start of the bucket, aligned to the project reporting timezone rather than to UTC.';
COMMENT ON COLUMN "metric_snapshots"."dimension_key" IS 'Breakdown dimension, e.g. country. The literal all means the ungrouped total, so totals and breakdowns share one table.';
COMMENT ON COLUMN "metric_snapshots"."dimension_value" IS 'Breakdown value. High-cardinality dimensions are truncated to a top-N plus an other bucket before they reach this table.';
COMMENT ON COLUMN "metric_snapshots"."value" IS 'The computed number. Numeric rather than float, because a dashboard that shows a different total on refresh destroys trust faster than a slow query.';
COMMENT ON COLUMN "metric_snapshots"."computed_at" IS 'When the rollup ran. A bucket can be recomputed after late events arrive, and this says which version you are looking at.';

CREATE UNIQUE INDEX "uq_snapshots_metric_bucket"
ON "metric_snapshots" ("project_id", "metric_key", "grain", "bucket_start", "dimension_key", "dimension_value");
CREATE INDEX "idx_snapshots_project_bucket"
ON "metric_snapshots" ("project_id", "bucket_start");

